CREATE TEMPORARY VIEW raw_tracking_${grass_region_without_quote} AS
        SELECT  user_id
                ,COALESCE(CAST(is_ads AS string), 'false') AS is_ads
                ,COALESCE(platform, 'unknown') as platform
                ,feature_detail
                ,upstream_feature
                ,exp_group_ids
                ,SUM(CASE WHEN operation = 'impression' THEN operation_cnt ELSE 0 END) AS imp_cnt
                ,SUM(CASE WHEN operation = 'click' THEN operation_cnt ELSE 0 END) AS click_cnt
                ,SUM(CASE WHEN operation = 'impression' AND feature_detail LIKE '%item' THEN operation_cnt ELSE 0 END) AS item_imp_cnt
                ,SUM(CASE WHEN operation = 'click' AND feature_detail LIKE '%item' THEN operation_cnt ELSE 0 END) AS item_click_cnt
                ,SUM(CASE WHEN operation = 'cart' THEN operation_cnt ELSE 0 END) AS cart_cnt
                ,SUM(CASE WHEN operation = 'ppv' THEN operation_cnt ELSE 0 END) AS ppv_cnt
                ,SUM(CASE WHEN operation = 'ppv' AND is_back IS NOT TRUE THEN operation_cnt ELSE 0 END) AS ppv_cnt_exclude_isback
                ,SUM(CASE WHEN operation = 'order' THEN operation_cnt ELSE 0 END) AS order_cnt
                ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv ELSE 0 END) AS gmv
        FROM    srdi_mart.dwd_sr_data_warehouse_platform
        WHERE   grass_region IN (${grass_region})
                AND  local_date = ${local_date}
                AND  SIZE(FILTER(exp_group_ids, value -> value > 0)) > 0
                AND  feature_detail LIKE 'product-you_may_also_like%'
                AND  reporting_object IN ('you may also like')
                AND  user_id > 0
                AND  operation IN ('impression','click','ppv','cart','order')
        GROUP BY 1, 2, 3, 4, 5, 6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW base_table_exploded_${grass_region_without_quote} AS
       SELECT  user_id
               ,is_ads
               ,platform
               ,feature_detail
               ,upstream_feature
               ,exp_group_id
               ,imp_cnt
               ,click_cnt
               ,item_imp_cnt
               ,item_click_cnt
               ,cart_cnt
               ,ppv_cnt_exclude_isback
               ,order_cnt
               ,gmv
       FROM raw_tracking_${grass_region_without_quote}
       LATERAL VIEW EXPLODE(exp_group_ids) AS exp_group_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_filter_${grass_region_without_quote} AS
select
    exp_group_id
from
    srdi_mart.dim_sr_data_warehouse_abtest_group
where
    local_date = ${local_date}
    and is_rcmd_scene_whitelist = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW base_table_exploded_exp_filtered_${grass_region_without_quote} AS
        SELECT a.*
        FROM base_table_exploded_${grass_region_without_quote} a
        INNER JOIN exp_filter_${grass_region_without_quote} b
        ON a.exp_group_id = b.exp_group_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW metrics_agg_${grass_region_without_quote} AS
SELECT is_ads
       ,platform
       ,upstream_feature
       ,feature_detail
       ,exp_group_id
       ,COUNT(DISTINCT CASE WHEN imp_cnt > 0 THEN user_id ELSE NULL END) AS imp_uu
       ,COUNT(DISTINCT CASE WHEN click_cnt > 0 THEN user_id ELSE NULL END) AS click_uu
       ,COUNT(DISTINCT CASE WHEN item_imp_cnt > 0 THEN user_id ELSE NULL END) AS item_imp_uu
       ,COUNT(DISTINCT CASE WHEN item_click_cnt > 0 THEN user_id ELSE NULL END) AS item_click_uu
       ,COUNT(DISTINCT CASE WHEN ppv_cnt_exclude_isback > 0 THEN user_id ELSE NULL END) AS ppv_uu
       ,COUNT(DISTINCT CASE WHEN cart_cnt > 0 THEN user_id ELSE NULL END) AS atc_uu
       ,COUNT(DISTINCT CASE WHEN order_cnt > 0 THEN user_id ELSE NULL END) AS order_uu
       ,SUM(CASE WHEN imp_cnt > 0 THEN imp_cnt ELSE 0 END) AS imp_cnt
       ,SUM(CASE WHEN click_cnt > 0 THEN click_cnt ELSE 0 END) AS click_cnt
       ,SUM(CASE WHEN item_imp_cnt > 0 THEN item_imp_cnt ELSE 0 END) AS item_imp_cnt
       ,SUM(CASE WHEN item_click_cnt > 0 THEN item_click_cnt ELSE 0 END) AS item_click_cnt
       ,SUM(CASE WHEN ppv_cnt_exclude_isback > 0 THEN ppv_cnt_exclude_isback ELSE 0 END) AS ppv_cnt_exclude_isback
       ,SUM(CASE WHEN cart_cnt > 0 THEN cart_cnt ELSE 0 END) AS cart_cnt
       ,SUM(CASE WHEN order_cnt > 0 THEN order_cnt ELSE 0 END) AS order_cnt
       ,SUM(CASE WHEN gmv > 0 THEN gmv ELSE 0 END) AS gmv
FROM base_table_exploded_exp_filtered_${grass_region_without_quote}
GROUP BY GROUPING SETS (
   (is_ads, platform, upstream_feature, feature_detail, exp_group_id),
   (is_ads, upstream_feature, feature_detail, exp_group_id),
   (platform, upstream_feature, feature_detail, exp_group_id),
   (upstream_feature, feature_detail, exp_group_id)
);

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_rcmd_exp_upstream_level_metrics_1d
PARTITION (
           grass_region = ${grass_region},
