       ,click_cnt
       ,item_imp_cnt
       ,item_click_cnt
       ,ppv_cnt_exclude_isback
       ,cart_cnt
       ,order_cnt
       ,gmv
       ,imp_uu
       ,click_uu
       ,item_imp_uu
       ,item_click_uu
       ,ppv_uu
       ,atc_uu
       ,order_uu
FROM metrics_agg_${grass_region_without_quote};
